// Code Node - Preparar Dados para o AI Agent Editor
// Extrai o post atual e prepara o contexto para revisao

const post = $json;

// Validacao
if (!post || !post.id) {
  throw new Error('Post nao encontrado ou invalido');
}

// Monta o contexto para o Editor
const editorContext = {
  // Identificacao
  post_id: post.id,
  tier: post.tier || 'TIER_2',
  category: post.category || 'general',

  // Conteudo original
  original: {
    title: post.title || '',
    slug: post.slug || '',
    excerpt: post.excerpt || '',
    meta_title: post.meta_title || '',
    meta_description: post.meta_description || '',
    content_html: post.content_html || '',
    content_markdown: post.content_markdown || '',
    categories: post.categories || [],
    tags: post.tags || [],
    word_count: post.word_count || 0,
    reading_time_minutes: post.reading_time_minutes || 0
  },

  // Feedback do revisor (o mais importante!)
  review_notes: post.review_notes || 'Sem instrucoes especificas',

  // Metadados
  review_session_id: post.review_session_id,
  review_order: post.review_order,
  created_at: post.created_at
};

// Monta o prompt do usuario para o AI Agent
const userPrompt = `## POST PARA REVISAO

### FEEDBACK DO REVISOR (PRIORIDADE MAXIMA)
${editorContext.review_notes}

### CONTEUDO ATUAL
**Titulo:** ${editorContext.original.title}
**Slug:** ${editorContext.original.slug}
**Excerpt:** ${editorContext.original.excerpt}
**Meta Title:** ${editorContext.original.meta_title}
**Meta Description:** ${editorContext.original.meta_description}

**Categorias:** ${JSON.stringify(editorContext.original.categories)}
**Tags:** ${JSON.stringify(editorContext.original.tags)}

**Conteudo HTML:**
${editorContext.original.content_html}

### INSTRUCOES
1. Leia atentamente o FEEDBACK DO REVISOR
2. Aplique TODAS as correcoes solicitadas
3. Mantenha o que NAO foi criticado
4. Preserve 100% dos dados numericos originais
5. Retorne o JSON completo com a versao corrigida`;

return {
  context: editorContext,
  user_prompt: userPrompt,
  post_id: post.id
};

// Code Node - Processar Resposta do AI Agent Editor
// Extrai o JSON da resposta e prepara para update no banco

const aiResponse = $json.output || $json.text || $json;
const context = $('PREPARAR PROMPT EDITOR').item.json.context;

// Tenta parsear a resposta do AI
let revisedContent;
try {
  // Se a resposta for string, faz parse
  if (typeof aiResponse === 'string') {
    // Remove possiveis markdown code blocks
    let cleanResponse = aiResponse
      .replace(/```json\n?/g, '')
      .replace(/```\n?/g, '')
      .trim();

    revisedContent = JSON.parse(cleanResponse);
  } else if (aiResponse.output) {
    // Se vier como objeto com output
    let cleanOutput = aiResponse.output
      .replace(/```json\n?/g, '')
      .replace(/```\n?/g, '')
      .trim();
    revisedContent = JSON.parse(cleanOutput);
  } else {
    revisedContent = aiResponse;
  }
} catch (e) {
  throw new Error('Erro ao parsear resposta do AI: ' + e.message + '. Resposta: ' + JSON.stringify(aiResponse).substring(0, 500));
}

// Valida campos obrigatorios
if (!revisedContent.title || !revisedContent.content_html) {
  throw new Error('Resposta do AI nao contem campos obrigatorios (title, content_html)');
}

// Calcula word_count e reading_time se nao vieram
const textContent = (revisedContent.content_html || '').replace(/<[^>]*>/g, ' ').trim();
const wordCount = revisedContent.word_count || textContent.split(/\s+/).filter(w => w.length > 0).length;
const readingTime = revisedContent.reading_time_minutes || Math.ceil(wordCount / 200);

// Prepara dados para update em content_posts
const contentPostsUpdate = {
  post_id: context.post_id,
  title: revisedContent.title,
  slug: revisedContent.slug || context.original.slug,
  excerpt: revisedContent.excerpt || context.original.excerpt,
  content_html: revisedContent.content_html,
  content_markdown: revisedContent.content_markdown || context.original.content_markdown,
  word_count: wordCount,
  reading_time_minutes: readingTime,
  updated_at: new Date().toISOString()
};

// Prepara dados para update em content_metadata
const contentMetadataUpdate = {
  post_id: context.post_id,
  meta_title: revisedContent.meta_title || revisedContent.title,
  meta_description: revisedContent.meta_description || revisedContent.excerpt,
  categories: revisedContent.categories || context.original.categories,
  tags: revisedContent.tags || context.original.tags,
  updated_at: new Date().toISOString()
};

// Prepara dados para update em content_workflow
const contentWorkflowUpdate = {
  post_id: context.post_id,
  status: 'draft', // Volta para draft para nova revisao
  review_notes: null, // Limpa as notas apos aplicar
  revision_count: 1, // Incrementar se existir campo
  updated_at: new Date().toISOString()
};

return {
  content_posts: contentPostsUpdate,
  content_metadata: contentMetadataUpdate,
  content_workflow: contentWorkflowUpdate,
  changes_made: revisedContent.changes_made || ['Revisao aplicada'],
  review_session_id: context.review_session_id,
  review_order: context.review_order
};

// Code Node - Preparar Notificacao de Revisao Concluida

const processedData = $('PROCESSAR RESPOSTA AI').item.json;
const contentPosts = processedData.content_posts;
const changesMade = processedData.changes_made || [];

const chatId = "8375309778";

const messageText = `*REVISAO APLICADA*\n\n*Post:* ${contentPosts.title.substring(0, 50)}...\n\n*Alteracoes feitas:*\n${changesMade.map(c => '- ' + c).join('\n')}\n\nPost retornou para fila de revisao.\n_Voce recebera a nova versao em breve._\n\n_ID: ${contentPosts.post_id.substring(0, 8)}_`;

return {
  telegram_payload: {
    chat_id: chatId,
    text: messageText,
    parse_mode: "Markdown"
  },
  post_id: contentPosts.post_id,
  title: contentPosts.title,
  changes_count: changesMade.length
};
